import type { IconifyJSON } from '@iconify/types';
import { addCollection } from '@iconify/vue';
import custom from './iconSubsets/custom.json';
import heroicons from './iconSubsets/heroicons.json';
import lucide from './iconSubsets/lucide.json';

// Offline Iconify registration (self-hosted — no runtime calls to the
// Iconify API). Only the strict icon subsets generated by
// `pnpm run icons:build` (scripts/build-icon-subsets.mjs) from the icon
// manifests ship to the browser — the full heroicons/lucide packs
// (~1.2 MB raw) would bloat the app chunk. devicon registers statically
// in the TechSkills page (race-free at page load, without bloating the
// app bundle); simple-icons registers in the features that consume them.
addCollection(heroicons as IconifyJSON);

// The lucide subset covers only the two icons the TextEditor's
// subscript/superscript buttons need (heroicons has no sub/superscript
// glyphs) — the generated subset keeps the bundle flat while
// staying offline.
addCollection(lucide as IconifyJSON);

// The hand-fed custom subset (SVGs dropped into resources/icons/custom,
// scripts/build-custom-icons.mjs) ships glyphs that do not exist in
// Iconify, e.g. a messenger mark for a contact row. It is tiny and
// registered here (not lazily) so every surface — admin rows, public
// blocks, SSR — can render `custom:*` icons without a readiness gate.
addCollection(custom as IconifyJSON);
